from collections import defaultdict

orders = [('Delhi', 450), ('Pune', 300), ('Delhi', 120), ('Pune', 80), ('Goa', 999)]

by_city = defaultdict(list)
for city, amount in orders:
    by_city[city].append(amount)

summary = {city: sum(vals) for city, vals in by_city.items()}
print(summary)  # {'Delhi': 570, 'Pune': 380, 'Goa': 999}

top = sorted(summary.items(), key=lambda kv: -kv[1])[0]
print(top)      # ('Goa', 999)
